<#
.SYNOPSIS
Builds one normalized section from Managed Secrets Exposure and gMSA Retrieval Principals evidence.
.NOTES
Version: 1.0.9
#>
[CmdletBinding()]
param(
 [Parameter(Mandatory)][string]$ManagedSecretsCollectionDirectory,
 [Parameter(Mandatory)][string]$GmsaCollectionDirectory,
 [string]$OutputDirectory,
 [string]$RepositoryRoot=(Resolve-Path(Join-Path $PSScriptRoot '..\..')).Path,
 [ValidateSet('Plan','Audit','Analyze','Resume','Standalone')][string]$Mode='Analyze',
 [ValidateSet('Quick','Full','Standalone','NotApplicable')][string]$Profile='Standalone',
 [switch]$OpenHtml,[switch]$NoColor
)
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop';$Version='1.0.9'
function Full([string]$P){if([IO.Path]::IsPathRooted($P)){[IO.Path]::GetFullPath($P)}else{[IO.Path]::GetFullPath((Join-Path(Get-Location).Path $P))}}
function Say($S,$M,$C=[ConsoleColor]::Gray){if($NoColor){Write-Host('[{0,-8}] {1}'-f$S,$M)}else{Write-Host('[{0,-8}] {1}'-f$S,$M)-ForegroundColor $C}}
function Arr([string]$P){if( -not (Test-Path -LiteralPath $P)){throw "Evidence missing: $P"};@(Get-Content -LiteralPath $P -Raw|ConvertFrom-Json)}
function Metric($I,$L,$V,$S,$D){[pscustomobject][ordered]@{id=$I;label=$L;value=$V;state=$S;description=$D}}
function Finding{param([string]$Id,[string]$Title,[string]$Disposition,[string]$Summary,[string[]]$Evidence=@(),[string[]]$Limitations=@(),[string]$Recommendation,[string]$Priority);[pscustomobject][ordered]@{id=$Id;title=$Title;disposition=$Disposition;summary=$Summary;evidence=@($Evidence);limitations=@($Limitations);recommendation=$Recommendation;priority=$Priority}}
$Started=(Get-Date).ToUniversalTime();$ManagedSecretsCollectionDirectory=Full $ManagedSecretsCollectionDirectory;if([string]::IsNullOrWhiteSpace($GmsaCollectionDirectory)){$CollectionRoot=Split-Path -Parent $ManagedSecretsCollectionDirectory;$Candidate=Get-ChildItem -LiteralPath $CollectionRoot -Directory -Filter 'GmsaRetrievalPrincipals-*' -ErrorAction SilentlyContinue|Sort-Object LastWriteTimeUtc -Descending|Select-Object -First 1;if($null -eq $Candidate){throw "Sibling gMSA collection not found under: $CollectionRoot"};$GmsaCollectionDirectory=$Candidate.FullName};$GmsaCollectionDirectory=Full $GmsaCollectionDirectory;$RepositoryRoot=Full $RepositoryRoot
foreach($D in @($ManagedSecretsCollectionDirectory,$GmsaCollectionDirectory)){if( -not (Test-Path -LiteralPath $D -PathType Container)){throw "Collection directory not found: $D"}}
if([string]::IsNullOrWhiteSpace($OutputDirectory)){$OutputDirectory=Join-Path $ManagedSecretsCollectionDirectory 'Analysis'};$OutputDirectory=Full $OutputDirectory;New-Item -ItemType Directory -Path $OutputDirectory -Force|Out-Null
$Reporting=Join-Path $RepositoryRoot 'Common\MSADPT.Reporting.psm1';$Analyzer=Join-Path $RepositoryRoot 'Modules\ObjectControl\Analyze-MSADPTManagedSecretsExposure-v1.0.0.ps1';foreach($P in @($Reporting,$Analyzer)){if( -not (Test-Path -LiteralPath $P)){throw "Required component missing: $P"}};Import-Module $Reporting -Force
$Analysis=Join-Path $OutputDirectory 'ManagedSecrets';New-Item -ItemType Directory -Path $Analysis -Force|Out-Null
Say INFO "Managed secrets: $ManagedSecretsCollectionDirectory" Cyan;Say INFO "gMSA retrieval: $GmsaCollectionDirectory" Cyan;Say INFO 'Network activity: None; directory changes: None; secret values collected: None.' Green
# Invoke the repository analyzer directly with its declared parameter contract.
# Avoid Get-Command -LiteralPath because its script discovery behavior differs between
# Windows PowerShell 5.1 and PowerShell 7.
$AnalyzerResult=& $Analyzer `
 -InventoryEvidenceDirectory $ManagedSecretsCollectionDirectory `
 -DelegationEvidenceDirectory $ManagedSecretsCollectionDirectory `
 -OutputDirectory $Analysis
$SummaryPath=Join-Path $Analysis 'managed-secrets-summary.json';if( -not (Test-Path -LiteralPath $SummaryPath)){throw "Managed secrets summary not created: $SummaryPath"};$Summary=Get-Content $SummaryPath -Raw|ConvertFrom-Json
$ManagedFindingsPath=Join-Path $Analysis 'managed-secrets-findings.csv';$ManagedFindings=@(if(Test-Path $ManagedFindingsPath){Import-Csv $ManagedFindingsPath}else{@()})
$GmsaManifestPath=Join-Path $GmsaCollectionDirectory 'evidence-manifest.json';$GmsaManifest=Get-Content $GmsaManifestPath -Raw|ConvertFrom-Json
$GmsaRaw=Join-Path $GmsaCollectionDirectory 'Raw';$Configured=@(Arr(Join-Path $GmsaRaw 'configured-principals.json'));$Effective=@(Arr(Join-Path $GmsaRaw 'effective-principal-relationships.json'));$Intersections=@(Arr(Join-Path $GmsaRaw 'privilege-intersections.json'));$Unresolved=@(Arr(Join-Path $GmsaRaw 'unresolved-principals.json'));$Unavailable=@(Arr(Join-Path $GmsaRaw 'unavailable-privileged-groups.json'));$GmsaErrors=@(Arr(Join-Path $GmsaRaw 'operational-errors.json'))
$OperationalErrorCount=[int]$Summary.InventoryOperationalErrorCount+[int]$Summary.DelegationOperationalErrorCount+$GmsaErrors.Count;$ResolutionLimitationCount=$Unresolved.Count+$Unavailable.Count;$Incomplete=($OperationalErrorCount -gt 0 -or $ResolutionLimitationCount -gt 0)
$Metrics=@(
 Metric 'computers' 'Computer objects assessed' $Summary.ComputerCount 'Informational' 'Computer objects assessed for collected LAPS metadata.'
 Metric 'laps-gaps' 'Likely LAPS coverage gaps' $Summary.LikelyCoverageGapCount $(if($Summary.LikelyCoverageGapCount){'Attention'}else{'Good'}) 'Recently active enabled computers lacking collected expiration metadata.'
 Metric 'gmsa' 'gMSA accounts' $GmsaManifest.GmsaCount 'Informational' 'gMSA inventory used for retrieval-principal analysis.'
 Metric 'configured-retrievers' 'Configured retriever relationships' $GmsaManifest.ConfiguredRelationshipCount 'Informational' 'Configured principal relationships from managed-password retrieval descriptors.'
 Metric 'effective-retrievers' 'Effective retriever relationships' $GmsaManifest.EffectiveRelationshipCount 'Informational' 'Resolved and expanded effective retrieval relationships.'
 Metric 'privilege-intersections' 'Privileged retrieval intersections' $GmsaManifest.PrivilegeIntersectionCount $(if($GmsaManifest.PrivilegeIntersectionCount){'Attention'}else{'Good'}) 'Effective retrievers intersecting privileged group membership.'
 Metric 'unresolved' 'Unresolved configured principals' $GmsaManifest.UnresolvedConfiguredPrincipalCount $(if($GmsaManifest.UnresolvedConfiguredPrincipalCount){'Unavailable'}else{'Good'}) 'Configured retriever references that could not be resolved.'
 Metric 'errors' 'Operational errors' $OperationalErrorCount $(if($OperationalErrorCount -gt 0){'Attention'}else{'Good'}) 'Operational collection or analysis errors across both evidence families.'
)
$Findings=[Collections.Generic.List[object]]::new()
foreach($R in $ManagedFindings){$Disp=if($R.Disposition -eq 'Likely'){'Likely or probable'}elseif($R.Disposition -eq 'Confirmed'){'Confirmed'}else{'Inconclusive'};$Pri=if($Disp -eq 'Confirmed'){'High'}elseif($Disp -eq 'Likely or probable'){'Normal'}else{'Informational'};$Findings.Add((Finding -Id ("managed-{0}" -f ($Findings.Count+1)) -Title ("{0}: {1}" -f $R.Area,$R.Object) -Disposition $Disp -Summary ([string]$R.Evidence) -Evidence @('Derived from saved Managed Secrets evidence.') -Limitations @([string]$R.Limitation) -Recommendation ([string]$R.RecommendedValidation) -Priority $Pri))}
if($Intersections.Count){$Findings.Add((Finding -Id 'gmsa-privilege-intersections' -Title 'Privileged principals can retrieve one or more gMSA managed passwords' -Disposition 'Confirmed' -Summary "$($Intersections.Count) privileged retrieval intersections were resolved from configured and expanded relationships." -Evidence @("Configured relationships: $($Configured.Count).","Effective relationships: $($Effective.Count).","Privilege intersections: $($Intersections.Count).") -Limitations @('Authorization to retrieve a managed password does not prove that a secret was retrieved or misused.','No managed-password blob or secret value was requested or collected.') -Recommendation 'Review each privileged retrieval relationship for business necessity and reduce excessive retrieval scope.' -Priority 'Normal'))}
if($Unresolved.Count -or $Unavailable.Count){$Findings.Add((Finding -Id 'gmsa-resolution-limitations' -Title 'gMSA retrieval authorization contains unresolved coverage' -Disposition 'Inconclusive' -Summary "$($Unresolved.Count) configured principals and $($Unavailable.Count) privileged groups were unavailable for full resolution." -Evidence @("Unresolved configured principals: $($Unresolved.Count).","Unavailable privileged groups: $($Unavailable.Count).") -Limitations @('Unresolved or unavailable evidence must not be interpreted as absent authorization.') -Recommendation 'Resolve the remaining SIDs or groups through an approved directory interface before concluding effective retrieval scope.' -Priority 'Informational'))}
if($Findings.Count -eq 0){$Findings.Add((Finding -Id 'managed-secrets-no-adverse-finding' -Title 'No adverse managed-secret condition was detected' -Disposition 'Not detected' -Summary 'The saved evidence produced no Managed Secrets finding, privileged retrieval intersection, or unresolved retrieval reference.' -Evidence @("gMSA accounts: $($GmsaManifest.GmsaCount).","Effective retrieval relationships: $($GmsaManifest.EffectiveRelationshipCount).") -Limitations @('This conclusion is bounded by saved collection coverage and does not prove that no secret can be retrieved.') -Recommendation 'Retain periodic recertification of LAPS coverage and gMSA retrieval authorization.' -Priority 'Informational'))}
$HasConfirmed=@($Findings | Where-Object { $_.disposition -eq 'Confirmed' }).Count -gt 0;$HasLikely=@($Findings | Where-Object { $_.disposition -eq 'Likely or probable' }).Count -gt 0
$Disposition=if($HasConfirmed){'Confirmed'}elseif($Incomplete){'Inconclusive'}elseif($HasLikely){'Likely or probable'}else{'Not detected'};$Execution=if($Incomplete){'CompletedWithLimitations'}else{'Completed'};$Complete= -not $Incomplete
$Target=if($GmsaManifest.Server){[string]$GmsaManifest.Server}else{[string]$Summary.Domain};$Completed=(Get-Date).ToUniversalTime()
$EvidenceSpecs=@(@($ManagedSecretsCollectionDirectory,'ManagedSecrets'),@($GmsaCollectionDirectory,'GmsaRetrieval'))
$EvidenceRoot=Split-Path -Parent $ManagedSecretsCollectionDirectory
$Links=@();foreach($Spec in $EvidenceSpecs){$Base=$Spec[0];$Prefix=$Spec[1];foreach($F in Get-ChildItem -LiteralPath $Base -File -Recurse){$Rel=([IO.Path]::GetRelativePath($Base,$F.FullName)).Replace('\','/');$Canonical=([IO.Path]::GetRelativePath($ManagedSecretsCollectionDirectory,(Join-Path $EvidenceRoot (([IO.Path]::GetFileName($Base))+'\'+$Rel)))).Replace('\','/');$Media= switch($F.Extension.ToLowerInvariant()){'.csv'{'text/csv'}'.html'{'text/html'}'.htm'{'text/html'}'.txt'{'text/plain'}'.json'{'application/json'}default{'application/octet-stream'}};$Links+=[pscustomobject][ordered]@{label="$Prefix/$Rel";relativePath=$Canonical;mediaType=$Media;exists=$true}}}
$Section=New-MSADPTReportSection -ModuleId 'Analyze-MSADPTManagedSecretsAndGmsaRetrieval' -ModuleVersion $Version -Title 'Managed Secrets and gMSA Retrieval Principals' -Category 'Identity.ManagedSecrets' -ExecutionStatus $Execution -Mode $Mode -Profile $Profile -Target $Target -StartedUtc $Started.ToString('o') -CompletedUtc $Completed.ToString('o') -DurationSeconds ([math]::Round(($Completed-$Started).TotalSeconds,3)) -ReusedEvidence $true -NetworkExecuted $false -DirectoryChanges None -Disposition $Disposition -Summary 'LAPS coverage, managed-secret delegation candidates, and effective gMSA retrieval authorization were correlated without collecting secret values.' -Confidence $(if($Incomplete){'Medium'}else{'High'}) -EvidenceComplete $Complete -Metrics $Metrics -Findings @($Findings) -EvidenceLinks $Links -Limitations @('No password, managed-password blob, or secret value was requested or collected.','Delegation candidates require effective-access validation before remediation.','Configured retrieval scope and effective expanded retrieval scope are reported separately.') -Recommendations @('Recertify gMSA retrieval authorization against business need.','Validate LAPS coverage candidates with device activity, policy applicability, and business role.','Resolve unavailable identities before concluding absence of access.')
$Validation=Test-MSADPTReportSection -Section $Section -EvidenceRoot $ManagedSecretsCollectionDirectory;if( -not $Validation.valid){throw "Validation failed: $($Validation.errors-join'; ')"}
$Json=Join-Path $OutputDirectory 'managed-secrets-gmsa-report-section.json';$Html=Join-Path $OutputDirectory 'managed-secrets-gmsa-report-section.html';$Val=Join-Path $OutputDirectory 'managed-secrets-gmsa-report-section-validation.json';$Section|ConvertTo-Json -Depth 16|Set-Content $Json -Encoding UTF8;$Validation|ConvertTo-Json -Depth 8|Set-Content $Val -Encoding UTF8;$Fragment=ConvertTo-MSADPTReportSectionHtml -Section $Section -EvidenceLinkPrefix '../';[IO.File]::WriteAllText($Html,$Fragment,(New-Object Text.UTF8Encoding($false)))
Say PASS("Report section completed: disposition={0}; findings={1}; evidenceComplete={2}."-f$Disposition,$Findings.Count,$Complete) Green;Say REPORT $Html Cyan;if($OpenHtml){Start-Process $Html}
[pscustomobject][ordered]@{Status='Completed';Version=$Version;Disposition=$Disposition;ExecutionStatus=$Execution;ManagedSecretsFindingCount=$ManagedFindings.Count;GmsaCount=[int]$GmsaManifest.GmsaCount;EffectiveRelationshipCount=[int]$GmsaManifest.EffectiveRelationshipCount;PrivilegeIntersectionCount=[int]$GmsaManifest.PrivilegeIntersectionCount;FindingCount=$Findings.Count;EvidenceComplete=$Complete;ValidationErrors=$Validation.errorCount;ValidationWarnings=$Validation.warningCount;ReportSectionJsonPath=$Json;ReportSectionHtmlPath=$Html;ValidationPath=$Val;NetworkActivity='None';DirectoryChanges='None';SecretValuesCollected=$false}
